<section class="content-card"><div class="section-heading"><div><h2>Registros mestres de amostras</h2><p>Cadastre, envie e acompanhe amostras em um único fluxo.</p></div><?php if(\BloodHub\Core\Permission::can('samples.create')): ?><a class="button" href="/samples/create">Nova Amostra</a><?php endif; ?></div>
<form class="filter-bar" method="get" action="/samples"><input name="q" placeholder="Buscar identificação" value="<?= htmlspecialchars($filters['q'],ENT_QUOTES,'UTF-8') ?>"><select name="status"><option value="">Todos os status</option><?php foreach($statuses as $key=>$label): ?><option value="<?= $key ?>" <?= $filters['status']===$key?'selected':'' ?>><?= htmlspecialchars($label,ENT_QUOTES,'UTF-8') ?></option><?php endforeach; ?></select><select name="purpose"><option value="">Todas as finalidades</option><?php foreach($purposes as $key=>$label): ?><option value="<?= $key ?>" <?= $filters['purpose']===$key?'selected':'' ?>><?= htmlspecialchars($label,ENT_QUOTES,'UTF-8') ?></option><?php endforeach; ?></select><select name="unit_id"><option value="">Todas as unidades</option><?php foreach($units as $item): ?><option value="<?= (int)$item['id'] ?>" <?= (string)$filters['unit_id']===(string)$item['id']?'selected':'' ?>><?= htmlspecialchars($item['name'],ENT_QUOTES,'UTF-8') ?></option><?php endforeach; ?></select><select name="component_id"><option value="">Todos os hemocomponentes</option><?php foreach($components as $item): ?><option value="<?= (int)$item['id'] ?>" <?= (string)$filters['component_id']===(string)$item['id']?'selected':'' ?>><?= htmlspecialchars($item['name'],ENT_QUOTES,'UTF-8') ?></option><?php endforeach; ?></select><button class="button" type="submit">Filtrar</button><a class="button button-secondary" href="/samples">Limpar</a></form>
<div class="table-wrap"><table><thead><tr><th>Identificação</th><th>Finalidade</th><th>Unidade</th><th>Hemocomponente</th><th>Status</th><th>Cadastro</th><th></th></tr></thead><tbody><?php foreach($samples as $item): ?><tr><td><strong><?= htmlspecialchars($item['sample_code'],ENT_QUOTES,'UTF-8') ?></strong></td><td><?= htmlspecialchars($purposes[$item['purpose']]??'Outros',ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars($item['unit_name']??'—',ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars($item['component_name']??'—',ENT_QUOTES,'UTF-8') ?></td><td><span class="status status-<?= htmlspecialchars($item['status'],ENT_QUOTES,'UTF-8') ?>"><?= htmlspecialchars(\BloodHub\Core\StatusLabel::label($item['status']),ENT_QUOTES,'UTF-8') ?></span></td><td><?= date('d/m/Y H:i',strtotime($item['registered_at'])) ?></td><td><a class="table-action" href="/samples/view?id=<?= (int)$item['id'] ?>">Visualizar</a></td></tr><?php endforeach; ?><?php if(!$samples): ?><tr><td colspan="7" class="empty">Nenhuma amostra encontrada.</td></tr><?php endif; ?></tbody></table></div></section>
